                                None,
                            )
                        });
                    assert!(!refused);
                    result.map(|(resolved, work)| {
                        assert_eq!(work.reused(), 0);
                        resolved
                    })
                };
                // Complete programs on success, or all diagnostics in exact
                // order including spans/messages on refusal, stay identical.
                assert_eq!(run(true), run(false));
            }
        }
    }
