    }
    fn helper_call(body: &mut ResolvedExpr) -> &mut ResolvedExpr {
        if matches!(&body.kind, ResolvedExprKind::Block { .. }) {
            let ResolvedExprKind::Block { tail, .. } = &mut body.kind else {
                unreachable!()
            };
            helper_call(tail)
        } else {
            body
        }
    }
