        let current = parse(&SOURCE.replace("helper()+1", "helper()+2"));
        for attack in 0..3 {
            let mut stale = old.clone();
            let helper = stale
                .functions
                .iter_mut()
                .find(|f| f.id.as_str() == "reuse.helper")
                .unwrap();
            let ResolvedExprKind::Call {
