        mode: ResolvedMatchMode::Value,
        scrutinee,
        arms,
    } = &expression.kind
    else {
        return None;
    };
    let [arm] = arms.as_slice() else {
        return None;
    };
    let ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance: None,
        args,
    } = &scrutinee.kind
    else {
        return None;
    };
    let [view, index] = args.as_slice() else {
        return None;
    };
    let ResolvedMatchPattern::Variant {
        variant,
        case,
        fields,
    } = &arm.pattern
    else {
        return None;
    };
    let [field] = fields.as_slice() else {
        return None;
