        && expression.ownership == OwnershipMode::Value
        && callee.as_str() == crate::byte_ops::GET_ID
        && type_arguments.is_empty()
        && scrutinee.ty.is_compiler_byte_option()
        && scrutinee.ownership == OwnershipMode::Value
